INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Horizon Skills Academy W.L.L.","nameAr":"أكاديمية الأفق للمهارات ذ.م.م","shortEn":"Horizon Academy","shortAr":"أكاديمية الأفق","taglineEn":"Executive Training, Technical Bootcamps & Certifications","taglineAr":"التدريب التنفيذي والمعسكرات التقنية والشهادات المهنية","aboutEn":"Accredited vocational and executive training institute empowering professionals with cloud engineering, finance, and leadership programs.","aboutAr":"معهد تدريب مهني وتنفيذي معتمد يمكّن الكفاءات في الحوسبة السحابية والمالية والقيادة."},"hero":{"titleEn":"Horizon Academy — Executive Training, Technical Bootcamps & Certifications","titleAr":"أكاديمية الأفق — التدريب التنفيذي والمعسكرات التقنية والشهادات المهنية","ctaLabelEn":"Explore Horizon Academy","ctaLabelAr":"استكشف أكاديمية الأفق"},"featuredServices":[{"code":"SVC-CLD","en":"Cloud Architecture 12-Week Bootcamp","ar":"معسكر هندسة السحابة (12 أسبوعاً)","rate":650},{"code":"SVC-FIN","en":"Corporate IFRS Workshop","ar":"ورشة المعايير الدولية للتقارير المالية","rate":1800},{"code":"EDU-COR","en":"Corporate Leadership Upskilling Cohort","ar":"برامج تطوير القيادات التنفيذية للشركات","rate":1650},{"code":"EDU-PMP","en":"PMP & Agile Certification Bootcamp","ar":"معسكر الإعداد لشهادة إدارة المشاريع PMP","rate":280}]}'::jsonb, '{"company":{"nameEn":"Horizon Skills Academy W.L.L.","nameAr":"أكاديمية الأفق للمهارات ذ.م.م","shortEn":"Horizon Academy","shortAr":"أكاديمية الأفق","taglineEn":"Executive Training, Technical Bootcamps & Certifications","taglineAr":"التدريب التنفيذي والمعسكرات التقنية والشهادات المهنية","aboutEn":"Accredited vocational and executive training institute empowering professionals with cloud engineering, finance, and leadership programs.","aboutAr":"معهد تدريب مهني وتنفيذي معتمد يمكّن الكفاءات في الحوسبة السحابية والمالية والقيادة."},"hero":{"titleEn":"Horizon Academy — Executive Training, Techn