INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('76a1db08-5503-4e75-a6b6-ee335a76bb31', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Horizon Academy consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم أكاديمية الأفق دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('4c9040cc-ef37-40e4-a554-601a0e113fa6', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Horizon Academy operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات أكاديمية الأفق توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('7d530896-8d19-4315-ad5b-2343bdb28544', 'Are all Horizon Academy invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير أكاديمية الأفق متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200014672000002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200014672000002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('d295014d-07c4-4431-ad8f-46d0947b53de', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
